#include <metal_stdlib>
using namespace metal;
kernel void metalmind_kernel(device const float* x, device float* out, constant uint& B, constant uint& D, constant float& epsilon, uint3 tg_pos [[threadgroup_position_in_grid]], uint3 tpig [[thread_position_in_grid]], uint3 tpitg [[thread_position_in_threadgroup]], uint3 tptg [[threads_per_threadgroup]]) {
    (void)epsilon;
    (void)tpig;
    uint row = tg_pos.x;
    if (row >= B) return;
    if (D == 0u) return;
    uint tid = tpitg.x;
    uint tg = tptg.x;
    threadgroup float sdata[256];
    device const float* row_x = x + (ulong)row * (ulong)D;
    device float* row_out = out + (ulong)row * (ulong)D;
    if ((D & 3u) == 0u) {
        uint D4 = D >> 2;
        device const float4* row_x4 = reinterpret_cast<device const float4*>(row_x);
        device float4* row_out4 = reinterpret_cast<device float4*>(row_out);
        float local_max = -3.4028234663852886e+38f;
        for (uint i = tid; i < D4; i += tg) {
            float4 v = row_x4[i];
            float m = max(max(v.x, v.y), max(v.z, v.w));
            local_max = max(local_max, m);
        }
        sdata[tid] = local_max;
        threadgroup_barrier(mem_flags::mem_threadgroup);
        for (uint stride = tg >> 1; stride > 0u; stride >>= 1) {
            if (tid < stride) {
                float other = sdata[tid + stride];
                sdata[tid] = max(sdata[tid], other);
            }
            threadgroup_barrier(mem_flags::mem_threadgroup);
        }
        float row_max = sdata[0];
        float local_sum = 0.0f;
        for (uint i = tid; i < D4; i += tg) {
            float4 v = row_x4[i];
            float4 e = exp(v - row_max);
            local_sum += e.x + e.y + e.z + e.w;
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
        sdata[tid] = local_sum;
        threadgroup_barrier(mem_flags::mem_threadgroup);
        for (uint stride = tg >> 1; stride > 0u; stride >>= 1) {
            if (tid < stride) sdata[tid] += sdata[tid + stride];
            threadgroup_barrier(mem_flags::mem_threadgroup);
        }
        float inv_sum = 1.0f / sdata[0];
        for (uint i = tid; i < D4; i += tg) {
            float4 v = row_x4[i];
            float4 e = exp(v - row_max);
            row_out4[i] = e * inv_sum;
        }
        return;
    }
    float local_max = -3.4028234663852886e+38f;
    for (uint i = tid; i < D; i += tg) local_max = max(local_max, row_x[i]);
    sdata[tid] = local_max;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint stride = tg >> 1; stride > 0u; stride >>= 1) {
        if (tid < stride) sdata[tid] = max(sdata[tid], sdata[tid + stride]);
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    float row_max = sdata[0];
    float local_sum = 0.0f;
    for (uint i = tid; i < D; i += tg) local_sum += exp(row_x[i] - row_max);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    sdata[tid] = local_sum;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint stride = tg >> 1; stride > 0u; stride >>= 1) {
        if (tid < stride) sdata[tid] += sdata[tid + stride];
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    float inv_sum = 1.0f / sdata[0];
    for (uint i = tid; i < D; i += tg) row_out[i] = exp(row_x[i] - row_max) * inv_sum;
}

#include <metal_stdlib>
using namespace metal;
kernel void metalmind_kernel(device const float* x, device float* out, constant uint& B, constant uint& D, constant float& epsilon, uint3 threadgroup_position_in_grid [[threadgroup_position_in_grid]], uint3 thread_position_in_threadgroup [[thread_position_in_threadgroup]], uint3 threads_per_threadgroup [[threads_per_threadgroup]]) {
    uint row = threadgroup_position_in_grid.x;
    if (row >= B) {
        return;
    }
    uint tid = thread_position_in_threadgroup.x;
    uint nt = threads_per_threadgroup.x;
    threadgroup float shared_data[256];
    threadgroup float broadcast_val;
    device const float* row_ptr = x + ((uint64_t)row * (uint64_t)D);
    device float* out_ptr = out + ((uint64_t)row * (uint64_t)D);
    float local_max = -3.402823466e+38f;
    for (uint i = tid; i < D; i += nt) {
        local_max = max(local_max, row_ptr[i]);
    }
    shared_data[tid] = local_max;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint stride = nt / 2u; stride > 0u; stride = stride >> 1u) {
        if (tid < stride) {
            shared_data[tid] = max(shared_data[tid], shared_data[tid + stride]);
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (tid == 0u) {
        broadcast_val = shared_data[0];
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    float row_max = broadcast_val;
    float local_sum = 0.0f;
    for (uint i = tid; i < D; i += nt) {
        local_sum += exp(row_ptr[i] - row_max);
    }
    shared_data[tid] = local_sum;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint stride = nt / 2u; stride > 0u; stride = stride >> 1u) {
        if (tid < stride) {
            shared_data[tid] += shared_data[tid + stride];
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    if (tid == 0u) {
        broadcast_val = shared_data[0];
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    float inv_sum = 1.0f / broadcast_val;
    for (uint i = tid; i < D; i += nt) {
        out_ptr[i] = exp(row_ptr[i] - row_max) * inv_sum;
    }
}
